import pandas as pd
import yfinance as yf

# Load the stock data
stock_data = yf.download('AAPL', start='2020-01-01', end='2022-01-01')

# Create a dictionary with the stock names and their corresponding prices
stock_dict = {}
for index, row in stock_data.iterrows():
    stock_dict[row['Symbol']] = row['Close']

# Define the script to manipulate the data
def manipulate_data(data, action):
    print(f"Manipulating data... ({action})")
    # Apply the action to the data
    if action == "add":
        for stock, price in data.items():
            data[stock] += price
    elif action == "remove":
        for stock, price in data.items():
            data[stock] -= price
    elif action == "sort":
        data = sorted(data.items(), key=lambda x: x[1], reverse=True)
        print("Sorted data:")
        for index, (stock, price) in enumerate(data):
            print(f"{stock}: {price}")
    else:
        print(f"Invalid action: {action}")

# Use the script to manipulate the data
manipulate_data(stock_dict, "add")
```
